import json, datetime
ONES_TR = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS_TR = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIGIT_TR = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS_TR = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
ORD_TR = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']


def tr_w3(n):
    out = []
    h = n // 100
    if h:
        out.append('yüz' if h == 1 else ONES_TR[h] + ' yüz')
    t = (n % 100) // 10
    if t:
        out.append(TENS_TR[t])
    o = n % 10
    if o:
        out.append(ONES_TR[o])
    return ' '.join(out)


def tr_words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for size, name in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        g = n // size
        if g:
            if size == 1000 and g == 1:
                parts.append('bin')
            else:
                parts.append(tr_w3(g) + ' ' + name)
            n = n % size
    if n:
        parts.append(tr_w3(n))
    return ' '.join(parts)


def tr_suffix(text, apos):
    t = text.strip().lower()
    vowel = 'ı'
    for ch in reversed(t):
        if ch in 'aı':
            vowel = 'ı'; break
        if ch in 'ou':
            vowel = 'u'; break
        if ch in 'ei':
            vowel = 'i'; break
        if ch in 'öü':
            vowel = 'ü'; break
    cons = 't' if t and t[-1] in 'fsştçkhp' else 'd'
    return text + ("'" if apos else '') + cons + vowel + 'r'


UNITS = dict(TL=('Türk Lirası', 'lira', 'kuruş'), USD=('Dolar', 'dolar', 'sent'),
             EUR=('Euro', 'euro', 'sent'), GBP=('İngiliz Sterlini', 'sterlin', 'peni'))


def tr_money(x, cur):
    v = round(abs(float(x)) + 1e-9, 2)
    whole = int(v)
    frac = int(round((v - whole) * 100))
    full, unit, sub = UNITS[cur]
    if frac == 0:
        return tr_words(whole) + ' ' + full
    return tr_words(whole) + ' ' + unit + ' ' + tr_words(frac) + ' ' + sub


def tr_money_cop(x, cur):
    v = round(abs(float(x)) + 1e-9, 2)
    s = tr_money(x, cur)
    if int(round((v - int(v)) * 100)) == 0:
        return tr_suffix(s, True)
    return tr_suffix(s, False)


def to_day(s):
    try:
        s = str(s).strip()
        if '.' in s:
            dd, mm, yy = s.split('.')[:3]
            return datetime.date(int(yy), int(mm), int(dd))
        return datetime.date.fromisoformat(s[:10])
    except Exception:
        return None


def tr_date(s):
    d = to_day(s)
    if d is None:
        return str(s)
    return str(d.day) + ' ' + MONTHS_TR[d.month - 1] + ' ' + str(d.year)


def tr_date_cop(s):
    d = to_day(s)
    if d is None:
        return str(s)
    return tr_date(s) + "'" + tr_suffix(tr_words(d.year), False)[len(tr_words(d.year)):]


def tr_digits(s):
    return ' '.join(DIGIT_TR[int(c)] for c in str(s) if c.isdigit())


def num(x):
    try:
        return float(x)
    except Exception:
        return 0.0


def card_intro(last4, name):
    if str(name or '').strip():
        return 'Sonu ' + tr_digits(last4) + ' ile biten ' + str(name).strip() + ' kartınız'
    return 'Sonu ' + tr_digits(last4) + ' ile biten kartınız'


def build_reading(d, today, name_fallback):
    """d: the bank's data object of cards.balance. Returns the full reading text."""
    name = d.get('productName')
    if not str(name or '').strip():
        name = name_fallback or ''
    intro = card_intro(d.get('cardNumberLast4') or '', name)
    stmt = d.get('statementDate')
    due = d.get('lastPayDate')
    dstmt = to_day(stmt)
    ddue = to_day(due)
    blocks = []
    for cur, key in (('TL', 'debtTL'), ('USD', 'debtUSD'), ('EUR', 'debtEUR'), ('GBP', 'debtGBP')):
        b = d.get(key)
        if isinstance(b, dict) and len(b) > 0:
            blocks.append((cur, b))
    tl_total = 0.0
    for cur, b in blocks:
        if cur == 'TL':
            tl_total = num(b.get('totalDebt'))
    owing = [(cur, b) for cur, b in blocks if num(b.get('remainingDebt')) > 0]
    clear = [UNITS[cur][0] for cur, b in blocks if num(b.get('remainingDebt')) <= 0]
    status = str(d.get('statementPaymentStatus') or '')
    out = []
    if dstmt is None:
        return intro + 'a ait kesilmiş bir ekstre bulunmadığından borcunuz bulunmamaktadır.'
    if today is not None and dstmt == today:
        out.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
        if tl_total > 0:
            out.append(intro + 'a ait toplam borcunuz ' + tr_money_cop(tl_total, 'TL') + '.')
        return ' '.join(out)
    if status == 'NO_DEBT' or len(owing) == 0:
        s = intro + 'ın ' + tr_date(stmt) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
        if tl_total > 0:
            s += ' Gelecek dönemler dahil toplam borcunuz ' + tr_money_cop(tl_total, 'TL') + '.'
        if due:
            s += ' Son ödeme tarihiniz ' + tr_date(due) + ' olacaktır.'
        return s
    first = True
    for cur, b in owing:
        xxx = tr_money(b.get('statementDebt'), cur)
        zzz = tr_money(b.get('minPayment'), cur)
        yyy = tr_money(b.get('remainingDebt'), cur)
        rem_min = num(b.get('remainingMinPayment'))
        mn = num(b.get('minPayment'))
        if cur == 'TL':
            if rem_min > 0 and rem_min >= mn:
                s = 'Türk Lirası borcunuz ' + xxx + ', ödenmesi gereken minimum tutar ' + tr_money_cop(b.get('minPayment'), cur) + '.'
            elif rem_min <= 0:
                s = 'Türk Lirası borcunuz ' + xxx + ', kalan toplam borcunuz ' + tr_money_cop(b.get('remainingDebt'), cur) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
            else:
                s = 'Türk Lirası borcunuz ' + xxx + ', ödenmesi gereken minimum tutar ' + zzz + ', kalan toplam borcunuz ' + yyy + ', kalan minimum ödeme tutarınız ' + tr_money_cop(rem_min, cur) + '.'
        else:
            s = UNITS[cur][0] + ' borcunuz ' + xxx + ', kalan toplam borcunuz ' + yyy + ', ödenmesi gereken minimum tutar ' + tr_money_cop(b.get('minPayment'), cur) + '.'
        if first:
            s = intro + 'a ait ' + tr_date(stmt) + ' tarihinde kesilen ekstre ' + s
            first = False
        out.append(s)
    if clear:
        if len(clear) == 1:
            names = clear[0]
        else:
            names = ', '.join(clear[:-1]) + ' ve ' + clear[-1]
        out.append(names + ' borcunuz bulunmamaktadır.')
    passed = today is not None and ddue is not None and today > ddue
    if passed and str(d.get('automaticPaymentFlag') or '') == 'Y':
        for cur, b in blocks:
            if cur == 'TL' and num(b.get('remainAutomaticPaymentAmount')) > 0:
                out.append('Otomatik ödeme talimatınızdan alınacak kalan tutar ' + tr_money_cop(b.get('remainAutomaticPaymentAmount'), 'TL') + '.')
    if ddue is not None:
        if today is not None and ddue == today:
            out.append('Borçlarınız için son ödeme tarihiniz bugündür.')
        elif passed:
            out.append('Borçlarınız için son ödeme tarihiniz olan ' + tr_date(due) + ' geçmiştir.')
            if tl_total > 0:
                out.append('Gelecek dönemler dahil toplam borcunuz ' + tr_money_cop(tl_total, 'TL') + '.')
        else:
            out.append('Borçlarınız için son ödeme tarihiniz ' + tr_date_cop(due) + '.')
    return ' '.join(out)


def bank_data(result):
    """From an api_call envelope: (ok, bank data dict, return code, http status)."""
    body = result.get('data') if isinstance(result, dict) else None
    if isinstance(body, str):
        try:
            body = json.loads(body)
        except Exception:
            body = None
    if not isinstance(body, dict):
        body = dict()
    res = body.get('result') if isinstance(body.get('result'), dict) else dict()
    code = str(res.get('returnCode') or res.get('code') or '')
    try:
        http = int(result.get('status_code') or 0)
    except Exception:
        http = 0
    inner = body.get('data') if isinstance(body.get('data'), dict) else dict()
    ok = code == '1' and (http == 0 or http < 400)
    return ok, inner, code, http


def today_from(v):
    try:
        return datetime.date.fromisoformat(str(v.get('now'))[:10])
    except Exception:
        return None

