def bank_data(result):
    """From an api_call envelope: (ok, bank data dict, return code, http status)."""
    body = result.get('data') if isinstance(result, dict) else None
    if isinstance(body, str):
        try:
            body = json.loads(body)
        except Exception:
            body = None
    if not isinstance(body, dict):
        body = dict()
    res = body.get('result') if isinstance(body.get('result'), dict) else dict()
    code = str(res.get('returnCode') or res.get('code') or '')
    try:
        http = int(result.get('status_code') or 0)
    except Exception:
        http = 0
    inner = body.get('data') if isinstance(body.get('data'), dict) else dict()
    ok = code == '1' and (http == 0 or http < 400)
    return ok, inner, code, http


